-- Completa as disciplinas gerais herdadas do catálogo inicial.
begin;
insert into discipline_subjects (discipline_id,name,slug,position)
select d.id,v.name,v.slug,v.position from disciplines d join (values
 ('direito-civil','Parte Geral','parte-geral-civil',10),('direito-civil','Obrigações','obrigacoes-civil',20),('direito-civil','Contratos','contratos-civil',30),
 ('direito-processual-civil','Jurisdição e Competência','jurisdicao-competencia-civil',10),('direito-processual-civil','Processo de Conhecimento','processo-conhecimento-civil',20),('direito-processual-civil','Recursos','recursos-civil',30),
 ('direito-tributario','Sistema Tributário','sistema-tributario',10),('direito-tributario','Obrigação Tributária','obrigacao-tributaria',20),('direito-tributario','Crédito Tributário','credito-tributario',30),
 ('direito-trabalho','Relação de Emprego','relacao-emprego',10),('direito-trabalho','Contrato de Trabalho','contrato-trabalho',20),('direito-trabalho','Direitos Trabalhistas','direitos-trabalhistas',30),
 ('direito-processual-trabalho','Organização da Justiça','organizacao-justica-trabalho',10),('direito-processual-trabalho','Dissídios','dissidios-trabalho',20),('direito-processual-trabalho','Recursos Trabalhistas','recursos-trabalhistas',30),
 ('direito-eleitoral','Direitos Políticos','direitos-politicos-eleitoral',10),('direito-eleitoral','Eleições','eleicoes-eleitoral',20),('direito-eleitoral','Partidos Políticos','partidos-politicos',30),
 ('direito-empresarial','Empresário','empresario',10),('direito-empresarial','Sociedades','sociedades-empresariais',20),('direito-empresarial','Títulos de Crédito','titulos-credito',30),
 ('administracao-publica','Organização Administrativa','organizacao-administrativa',10),('administracao-publica','Políticas Públicas','politicas-publicas',20),('administracao-publica','Governança Pública','governanca-publica',30),
 ('administracao-geral','Planejamento','planejamento-administracao',10),('administracao-geral','Gestão de Pessoas','gestao-pessoas',20),('administracao-geral','Processos Organizacionais','processos-organizacionais',30),
 ('contabilidade-geral','Fundamentos','fundamentos-contabilidade',10),('contabilidade-geral','Demonstrações Contábeis','demonstracoes-contabeis',20),('contabilidade-geral','Análise Contábil','analise-contabil',30),
 ('contabilidade-publica','Orçamento Público','orcamento-contabilidade-publica',10),('contabilidade-publica','Patrimônio Público','patrimonio-publico',20),('contabilidade-publica','Variações Patrimoniais','variacoes-patrimoniais',30),
 ('afo','Planejamento e Orçamento','planejamento-orcamento',10),('afo','Receita Pública','receita-publica',20),('afo','Despesa Pública','despesa-publica',30),
 ('economia','Microeconomia','microeconomia',10),('economia','Macroeconomia','macroeconomia',20),('economia','Economia do Setor Público','economia-setor-publico',30),
 ('estatistica','Estatística Descritiva','estatistica-descritiva',10),('estatistica','Probabilidade','probabilidade-estatistica',20),('estatistica','Inferência','inferencia-estatistica',30),
 ('arquivologia','Fundamentos da Arquivologia','fundamentos-arquivologia',10),('arquivologia','Gestão Documental','gestao-documental',20),('arquivologia','Preservação','preservacao-arquivistica',30),
 ('atualidades','Brasil Atual','brasil-atualidades',10),('atualidades','Mundo Atual','mundo-atualidades',20),('atualidades','Ciência e Tecnologia','ciencia-tecnologia-atualidades',30),
 ('etica-servico-publico','Princípios Éticos','principios-eticos',10),('etica-servico-publico','Conduta no Serviço Público','conduta-servico-publico',20),('etica-servico-publico','Responsabilidade','responsabilidade-etica',30),
 ('redacao-oficial','Princípios da Redação Oficial','principios-redacao-oficial',10),('redacao-oficial','Expedientes Oficiais','expedientes-oficiais',20),('redacao-oficial','Linguagem e Padronização','linguagem-redacao-oficial',30)
) v(discipline_slug,name,slug,position) on v.discipline_slug=d.slug
on conflict (discipline_id,slug) do update set name=excluded.name,position=excluded.position,is_active=true;

insert into discipline_topics (subject_id,name,slug,position)
select s.id,v.name,v.slug,10 from discipline_subjects s join (values
 ('parte-geral-civil','Pessoas e Bens','pessoas-bens-civil'),('obrigacoes-civil','Adimplemento','adimplemento-civil'),('contratos-civil','Formação Contratual','formacao-contratos'),
 ('jurisdicao-competencia-civil','Competência','competencia-civil'),('processo-conhecimento-civil','Petição Inicial','peticao-inicial-civil'),('recursos-civil','Apelação','apelacao-civil'),
 ('sistema-tributario','Princípios Tributários','principios-tributarios'),('obrigacao-tributaria','Fato Gerador','fato-gerador'),('credito-tributario','Lançamento','lancamento-tributario'),
 ('relacao-emprego','Requisitos','requisitos-emprego'),('contrato-trabalho','Alteração Contratual','alteracao-contrato-trabalho'),('direitos-trabalhistas','Jornada','jornada-trabalho'),
 ('organizacao-justica-trabalho','Varas e Tribunais','varas-tribunais-trabalho'),('dissidios-trabalho','Rito Ordinário','rito-ordinario-trabalho'),('recursos-trabalhistas','Recurso Ordinário','recurso-ordinario-trabalho'),
 ('direitos-politicos-eleitoral','Alistamento','alistamento-eleitoral'),('eleicoes-eleitoral','Sistemas Eleitorais','sistemas-eleitorais'),('partidos-politicos','Criação e Funcionamento','criacao-partidos'),
 ('empresario','Registro Empresarial','registro-empresarial'),('sociedades-empresariais','Sociedade Limitada','sociedade-limitada'),('titulos-credito','Características','caracteristicas-titulos'),
 ('organizacao-administrativa','Administração Direta e Indireta','direta-indireta'),('politicas-publicas','Ciclo de Políticas','ciclo-politicas'),('governanca-publica','Controle e Transparência','controle-transparencia'),
 ('planejamento-administracao','Planejamento Estratégico','planejamento-estrategico'),('gestao-pessoas','Liderança e Motivação','lideranca-motivacao'),('processos-organizacionais','Estruturas Organizacionais','estruturas-organizacionais'),
 ('fundamentos-contabilidade','Patrimônio','patrimonio-contabil'),('demonstracoes-contabeis','Balanço Patrimonial','balanco-patrimonial'),('analise-contabil','Índices Contábeis','indices-contabeis'),
 ('orcamento-contabilidade-publica','Ciclo Orçamentário','ciclo-orcamentario'),('patrimonio-publico','Bens Públicos','bens-publicos'),('variacoes-patrimoniais','Resultado Patrimonial','resultado-patrimonial'),
 ('planejamento-orcamento','PPA, LDO e LOA','ppa-ldo-loa'),('receita-publica','Classificação da Receita','classificacao-receita'),('despesa-publica','Estágios da Despesa','estagios-despesa'),
 ('microeconomia','Oferta e Demanda','oferta-demanda'),('macroeconomia','Inflação e Desemprego','inflacao-desemprego'),('economia-setor-publico','Política Fiscal','politica-fiscal'),
 ('estatistica-descritiva','Medidas de Posição','medidas-posicao'),('probabilidade-estatistica','Eventos','eventos-probabilidade'),('inferencia-estatistica','Amostragem','amostragem-estatistica'),
 ('fundamentos-arquivologia','Princípios Arquivísticos','principios-arquivisticos'),('gestao-documental','Classificação e Avaliação','classificacao-avaliacao'),('preservacao-arquivistica','Conservação','conservacao-documentos'),
 ('brasil-atualidades','Política Brasileira','politica-brasileira'),('mundo-atualidades','Geopolítica','geopolitica-atualidades'),('ciencia-tecnologia-atualidades','Transformação Digital','transformacao-digital'),
 ('principios-eticos','Moralidade e Impessoalidade','moralidade-impessoalidade'),('conduta-servico-publico','Deveres e Proibições','deveres-proibicoes'),('responsabilidade-etica','Comissões de Ética','comissoes-etica'),
 ('principios-redacao-oficial','Impessoalidade','impessoalidade-redacao'),('expedientes-oficiais','Ofício e Memorando','oficio-memorando'),('linguagem-redacao-oficial','Clareza e Concisão','clareza-concisao')
) v(subject_slug,name,slug) on v.subject_slug=s.slug
on conflict (subject_id,slug) do update set name=excluded.name,position=excluded.position,is_active=true;

insert into discipline_subtopics (topic_id,name,slug,position)
select t.id,v.name,v.slug,10 from discipline_topics t join (values
 ('pessoas-bens-civil','Personalidade','personalidade-civil'),('adimplemento-civil','Mora','mora-civil'),('formacao-contratos','Princípios Contratuais','principios-contratos'),('competencia-civil','Competência Absoluta e Relativa','competencia-absoluta-relativa'),('peticao-inicial-civil','Requisitos','requisitos-peticao-civil'),('apelacao-civil','Efeitos','efeitos-apelacao-civil'),('principios-tributarios','Limitações ao Poder de Tributar','limitacoes-tributar'),('fato-gerador','Obrigação Principal e Acessória','obrigacao-principal-acessoria'),('lancamento-tributario','Modalidades','modalidades-lancamento'),('requisitos-emprego','Pessoalidade e Subordinação','pessoalidade-subordinacao'),('alteracao-contrato-trabalho','Jus Variandi','jus-variandi'),('jornada-trabalho','Horas Extras','horas-extras'),('varas-tribunais-trabalho','Competência Material','competencia-material-trabalho'),('rito-ordinario-trabalho','Fases Processuais','fases-processuais-trabalho'),('recurso-ordinario-trabalho','Pressupostos','pressupostos-recurso-trabalho'),('alistamento-eleitoral','Domicílio Eleitoral','domicilio-eleitoral'),('sistemas-eleitorais','Majoritário e Proporcional','majoritario-proporcional'),('criacao-partidos','Fidelidade Partidária','fidelidade-partidaria'),('registro-empresarial','Empresário Individual','empresario-individual'),('sociedade-limitada','Quotas','quotas-sociedade'),('caracteristicas-titulos','Cartularidade','cartularidade'),('direta-indireta','Autarquias e Fundações','autarquias-fundacoes'),('ciclo-politicas','Agenda e Implementação','agenda-implementacao'),('controle-transparencia','Controle Social','controle-social'),('planejamento-estrategico','Missão e Visão','missao-visao'),('lideranca-motivacao','Teorias da Motivação','teorias-motivacao'),('estruturas-organizacionais','Departamentalização','departamentalizacao'),('patrimonio-contabil','Ativo e Passivo','ativo-passivo'),('balanco-patrimonial','Ativo Circulante','ativo-circulante'),('indices-contabeis','Liquidez','liquidez-contabil'),('ciclo-orcamentario','Elaboração e Aprovação','elaboracao-aprovacao-orcamento'),('bens-publicos','Bens de Uso Comum','bens-uso-comum'),('resultado-patrimonial','Variações Aumentativas e Diminutivas','variacoes-aumentativas-diminutivas'),('ppa-ldo-loa','Compatibilidade Orçamentária','compatibilidade-orcamentaria'),('classificacao-receita','Receitas Correntes','receitas-correntes'),('estagios-despesa','Empenho Liquidação e Pagamento','empenho-liquidacao-pagamento'),('oferta-demanda','Equilíbrio de Mercado','equilibrio-mercado'),('inflacao-desemprego','Políticas de Estabilização','politicas-estabilizacao'),('politica-fiscal','Tributação e Gasto','tributacao-gasto'),('medidas-posicao','Média Mediana e Moda','media-mediana-moda'),('eventos-probabilidade','Probabilidade Condicional','probabilidade-condicional'),('amostragem-estatistica','Estimadores','estimadores'),('principios-arquivisticos','Ciclo Vital','ciclo-vital-arquivos'),('classificacao-avaliacao','Tabela de Temporalidade','tabela-temporalidade'),('conservacao-documentos','Preservação Digital','preservacao-digital'),('politica-brasileira','Poderes da República','poderes-republica'),('geopolitica-atualidades','Conflitos e Blocos','conflitos-blocos'),('transformacao-digital','Inteligência Artificial','inteligencia-artificial'),('moralidade-impessoalidade','Valores do Serviço Público','valores-servico-publico'),('deveres-proibicoes','Código de Ética','codigo-etica'),('comissoes-etica','Apuração Ética','apuracao-etica'),('impessoalidade-redacao','Padrão Ofício','padrao-oficio'),('oficio-memorando','Estrutura do Expediente','estrutura-expediente'),('clareza-concisao','Adequação Vocabular','adequacao-vocabular')
) v(topic_slug,name,slug) on v.topic_slug=t.slug
on conflict (topic_id,slug) do update set name=excluded.name,position=excluded.position,is_active=true;
commit;
